mapper.insert:
insert game (game_id, home_api_id, away_api_id, home_score, away_score, date, result , round) values
( #{gameDto.gameId}, #{gameDto.homeTeamDto.teamId}, #{gameDto.awayTeamDto.teamId}, #{gameDto.homeScore}, #{gameDto.awayScore}, #{gameDto.dateTime}, #{gameDto.result}, #{gameDto.round} )
on DUPLICATE key update home_api_id = VALUES(home_api_id), away_api_id = VALUES(away_api_id), home_score = VALUES(home_score), away_score = VALUES(away_score), date = VALUES(date), result = VALUES(result), round = VALUES(round);
